'use strict';
// Local image previews and scripted fixtures only. No upload, OCR or model call.
let aiAttachmentActive=null,aiAttachmentSequence=0,aiAttachmentTrigger=null;
function aiImageFileError(file){return aiAttachmentFileError(file,aiAttachmentKind(file));}
function aiImageExample(kind='single'){if(['pdf','statement','protected'].includes(kind)){const statement=kind!=='pdf';return {id:'file-'+(++aiAttachmentSequence),src:'assets/attachment-'+(statement?'statement':'receipt')+'.pdf',name:statement?'Bank-statement.pdf':'Notion-receipt.pdf',mediaKind:'pdf',pages:statement?2:1,previewPages:Array.from({length:statement?2:1},(_,i)=>'assets/attachment-'+(statement?'statement':'receipt')+'-page-'+(i+1)+'.png'),fixture:kind==='protected'?'protected':statement?'statement':'single',owned:false};}return {id:'image-'+(++aiAttachmentSequence),src:'assets/attachment-'+(kind==='multi'?'multi':kind==='unclear'?'unclear':'receipt')+'.svg',name:kind==='multi'?'Subscription receipts':kind==='unclear'?'Receipt photo':'Notion receipt',mediaKind:'image',fixture:kind,owned:false};}
function aiImageIcon(kind){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${kind==='close'?'m6 6 12 12M18 6 6 18':kind==='photo'?'M4 4h16v16H4zM4 16l5-5 4 4 2-2 5 5M15 8h.01':'M15 3H5v18h14V7l-4-4Zm0 0v5h5M8 12h8M8 16h5'}"/></svg>`;}
function aiImagePreview(session){const pdf=session.image?.mediaKind==='pdf';return `${session.imageLoading?'<div class="ai-image-opening" role="status">Opening file…</div>':''}${session.image?`<div class="ai-image-preview"><button type="button" class="ai-image-preview-open ${pdf?'ai-pdf-thumbnail':''}" data-ai-image-preview aria-label="Preview selected ${pdf?'PDF':'image'}">${pdf?aiImageIcon('file')+'<b>PDF</b>':`<img src="${escape(session.image.src)}" alt="Selected image">`}</button><div><strong>${pdf?'PDF':'Image'} attached</strong><small>${escape(session.image.name)}${pdf&&session.image.pages?' · '+session.image.pages+' pages':''}</small></div><button type="button" class="ai-image-remove" data-ai-image-remove aria-label="Remove selected attachment">${aiImageIcon('close')}</button></div>`:''}${session.imageError?`<p class="ai-image-validation" role="alert">${escape(session.imageError)}</p>`:''}`;}
function aiImageMessage(m){const pdf=m.image.mediaKind==='pdf';return m.image.src?`<button class="${pdf?'ai-document-message':'ai-image-message'}" data-ai-image-open="${m.id}" aria-label="Preview sent ${pdf?'PDF':'image'}">${pdf?`<span class="ai-pdf-symbol">${aiImageIcon('file')}</span><span><strong>${escape(m.image.name)}</strong><small>PDF${m.image.pages?' · '+m.image.pages+' pages':''} · View document ↗</small></span>`:`<img src="${escape(m.image.src)}" alt="Attached subscription image"><span>View image ↗</span>`}</button>${m.text?`<p class="ai-image-caption">${escape(m.text)}</p>`:''}`:`<span class="ai-image-expired">${aiImageIcon('file')}Attachment no longer available</span>${m.text?`<p class="ai-image-caption">${escape(m.text)}</p>`:''}`;}
function aiImageFailure(m){return `<div class="ai-message-failure ai-image-failure" role="status"><span>${escape(m.failureText||'Couldn’t process this file.')}</span><div>${m.image.src&&!['unclear','protected'].includes(m.errorKind)?`<button data-ai-text-retry="${m.id}">Retry</button>`:''}${['unclear','protected'].includes(m.errorKind)?`<button data-ai-image-replace="${m.id}">Choose another file</button>`:`<button data-ai-image-discard="${m.id}">Remove</button>`}</div></div>`;}
function aiImageCandidateDrafts(image,sequence){if(!['single','multi','statement'].includes(image.fixture))return [];let rows=[{name:'Notion',price:'12.00',currency:'USD',cycle:'Monthly',category:'Productivity',renewal:'2026-11-25',sourceKind:'receipt'}];if(image.fixture==='multi')rows.push({name:'Figma',price:'15.00',currency:'USD',cycle:'Monthly',category:'Productivity',renewal:'2026-11-25',sourceKind:'receipt'});if(image.fixture==='statement')rows=[{name:'Notion',price:'12.00',currency:'USD',cycle:'',renewal:'',category:'Productivity',sourceKind:'statement',observedDate:'2026-10-25',observedAmount:'12.00',observedCurrency:'USD',observedCount:2,priceNeedsReview:true,evidencePage:2},{name:'Spotify',price:'11.99',currency:'USD',cycle:'',renewal:'',category:'Entertainment',sourceKind:'statement',observedDate:'2026-10-29',observedAmount:'11.99',observedCurrency:'USD',observedCount:2,priceNeedsReview:true,evidencePage:2}];return rows.map((r,i)=>({...r,id:'ai-image-'+sequence+'-'+i,inputMode:image.mediaKind==='pdf'?'pdf':'image',start:'',note:''}));}
function aiImageCandidateTabs(session){if(!session.imageFinds||session.imageFinds.length<2)return '';return `<div class="ai-image-candidates"><p>${session.imageFinds.length} plans to review <span>Review each plan</span></p><div role="group" aria-label="Choose a subscription to review">${session.imageFinds.map((entry,i)=>`<button data-ai-image-candidate="${i}" aria-pressed="${entry.draft.id===session.draft?.id}" ${session.thinking||session.saving||session.image||session.imageLoading||session.messages.some(m=>m.failed)?'disabled':''}>${escape(entry.draft.name)}${entry.saved||entry.draft.id===session.draft?.id&&session.saved?' ✓':''}</button>`).join('')}</div></div>`;}
function aiRememberImageCandidate(session){const index=session.imageFinds?.findIndex(entry=>entry.draft.id===session.draft?.id);if(index>=0)session.imageFinds[index]={draft:session.draft,saved:session.saved,invalid:session.invalidCorrection};}
function aiChooseImageCandidate(session,index){if(!session.imageFinds?.[index]||session.thinking||session.saving||session.image||session.imageLoading||session.messages.some(m=>m.failed))return;aiRememberImageCandidate(session);const entry=session.imageFinds[index];session.imageFindIndex=index;session.draft=entry.draft;session.saved=entry.saved;session.invalidCorrection=entry.invalid||false;aiRefreshConversation(session,true);}
function aiRevokeImage(image){if(image?.owned&&image.src)URL.revokeObjectURL(image.src);if(image){image.src='';image.file=null;}}
function disposeAiImages(session){if(!session)return;session.imageLoad=(session.imageLoad||0)+1;aiRevokeImage(session.image);session.image=null;session.imageLoading=false;session.imageError='';for(const m of session.messages.filter(m=>m.kind==='image')){aiRevokeImage(m.image);if(m.failed){m.failureText='Attachment no longer available. Attach it again.';m.errorKind='expired';}}if(session.imageProcessing){clearTimeout(session.timer);session.imageProcessing=false;session.thinking=false;const m=session.messages.findLast(m=>m.kind==='image');if(m){m.failed=true;m.failureText='File processing was interrupted. Attach it again.';m.errorKind='expired';}}}
function aiAttachmentAfterRender(session){if(aiAttachmentActive&&aiAttachmentActive!==session){disposeAiImages(aiAttachmentActive);aiAttachmentTrigger=null;aiPdfPreviewed=null;}aiAttachmentActive=session||null;}
function aiPickImage(kind='choose',trigger){const session=aiTextSession();if(session.thinking||session.saving||session.voiceRecording||session.imageLoading||session.messages.some(m=>m.failed))return;if(kind==='choose'){openAiAttachmentPicker(trigger||document.querySelector('[data-ai-text-later="attachment"]'));return;}closeAiImagePreview();const input=document.querySelector(kind==='pdf'?'[data-ai-pdf-file]':'[data-ai-image-file]');if(input){input.value='';input.click();}}
async function aiSelectImage(file,choice='image'){if(!file)return;const session=aiTextSession(),generation=(session.imageLoad||0)+1;session.imageLoad=generation;const error=aiAttachmentFileError(file,choice);if(error){session.imageLoading=false;session.imageError=error;aiRefreshComposer(session);return;}session.imageLoading=true;session.imageError='';aiRefreshComposer(session);aiRefreshConversation(session);const src=URL.createObjectURL(file);try{if(choice==='pdf'){if(await file.slice(0,5).text()!=='%PDF-')throw new Error('pdf');}else await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>img.naturalWidth*img.naturalHeight>24000000?reject(new Error('size')):resolve();img.onerror=()=>reject(new Error('decode'));img.src=src;});if(aiAttachmentActive!==session||session.imageLoad!==generation){URL.revokeObjectURL(src);return;}aiRevokeImage(session.image);session.imageLoading=false;session.image={id:'file-'+(++aiAttachmentSequence),src,name:file.name,file,mediaKind:choice,owned:true};session.imageError='';aiRefreshComposer(session);aiRefreshConversation(session);document.querySelector('#ai-text-input')?.focus();}catch(error){URL.revokeObjectURL(src);if(aiAttachmentActive!==session||session.imageLoad!==generation)return;session.imageLoading=false;session.imageError=error.message==='size'?'Choose an image up to 24 megapixels.':choice==='pdf'?'This PDF couldn’t be opened. Choose another file.':'This image couldn’t be opened. Choose another image.';aiRefreshComposer(session);}}
function aiSendImage(retryId){const session=aiTextSession();if(session.thinking||session.saving||session.voiceRecording||session.imageLoading)return;let message;if(retryId){message=session.messages.find(m=>m.id===retryId&&m.kind==='image'&&m.failed);if(!message?.image.src)return;message.failed=false;message.failureText='';}else{if(!session.image||session.messages.some(m=>m.failed))return;message={id:Date.now(),role:'user',kind:'image',image:session.image,text:session.input.trim()};session.messages.push(message);session.image=null;session.input='';session.imageError='';aiRefreshComposer(session);}session.thinking=true;session.imageProcessing=true;session.attachmentProcessingKind=message.image.mediaKind||'image';const generation=aiTextGeneration,forceFailure=session.failNext;session.failNext=false;document.querySelector('[data-ai-text-failure]')?.setAttribute('aria-pressed','false');aiRefreshConversation(session,true);clearTimeout(session.timer);session.timer=setTimeout(()=>{if(generation!==aiTextGeneration||!aiTextChats.has(aiTextKeyForSession(session)))return;session.thinking=false;session.imageProcessing=false;if(forceFailure){message.failed=true;message.errorKind='network';message.failureText='Couldn’t process this file. Please try again.';}else if(message.image.fixture==='protected'){message.failed=true;message.errorKind='protected';message.failureText='This PDF is password-protected. Attach an unlocked copy.';}else if(message.image.fixture==='unclear'){message.failed=true;message.errorKind='unclear';message.failureText='This image is hard to read. Try a clearer photo.';}else{const candidates=aiImageCandidateDrafts(message.image,++aiTextSequence).map(d=>aiGroundAttachmentDraft(d,typeof allTrackedRecords==='function'?allTrackedRecords():[],typeof manualServices!=='undefined'?manualServices:[]));if(!candidates.length){message.failed=true;message.errorKind='unavailable';message.failureText='File analysis is unavailable right now. Please try again.';}else{aiRememberImageCandidate(session);const earlier=[...(session.imageFinds||[])];if(session.draft&&!earlier.some(entry=>entry.draft.id===session.draft.id))earlier.push({draft:session.draft,saved:session.saved,invalid:session.invalidCorrection});session.imageFinds=[...earlier,...candidates.map(draft=>({draft,saved:false,invalid:false}))];session.imageFindIndex=earlier.length;session.draft=candidates[0];session.saved=false;session.invalidCorrection=false;session.messages.push({id:Date.now()+1,role:'assistant',text:message.image.fixture==='statement'?'I found 2 possible recurring charges. These are historical transactions—review the matching plans, amount, billing cycle and next renewal.':candidates.length>1?'I found 2 subscriptions. Review each plan and any existing matches before adding.':'I found the subscription details. Check any matching plan below before adding another.'});}}if(isAiChatScreen()&&aiTextSession()===session){aiRefreshConversation(session,false,true);aiSyncComposer();}},1500);}
function aiTextKeyForSession(session){return [...aiTextChats.entries()].find(([,value])=>value===session)?.[0];}
function closeAiImagePreview(){const overlay=document.querySelector('.ai-image-overlay');if(!overlay)return;const phone=overlay.closest('.phone');overlay.remove();phone.querySelectorAll('[data-ai-image-inert]').forEach(el=>{el.inert=false;el.removeAttribute('data-ai-image-inert');});if(aiAttachmentTrigger?.isConnected)aiAttachmentTrigger.focus();aiAttachmentTrigger=null;aiPdfPreviewed=null;}
function openAiImagePreview(trigger,image){if(!image?.src)return;if(image.mediaKind==='pdf'){aiPdfPreviewed=image;image.previewPage=0;aiAttachmentDialog(trigger,'PDF preview',aiPdfPreviewBody(image));}else aiAttachmentDialog(trigger,'Image preview',`<img src="${escape(image.src)}" alt="Selected subscription image">`);}
function aiRemoveImageMessage(session,id){const message=session.messages.find(m=>m.id===id&&m.kind==='image'&&m.failed);if(!message)return;aiRevokeImage(message.image);session.messages=session.messages.filter(m=>m!==message);aiRefreshConversation(session);aiSyncComposer();}
document.addEventListener('change',e=>{if(e.target.matches('[data-ai-image-file],[data-ai-pdf-file]'))aiSelectImage(e.target.files[0],e.target.matches('[data-ai-pdf-file]')?'pdf':'image');});
document.addEventListener('click',e=>{const confirmName=e.target.closest('[data-ai-confirm-service]');if(confirmName){const session=aiTextSession();session.draft.platformNeedsReview=false;session.draft.platformNameConfirmed=aiNormalizeMerchant(session.draft.name);aiAttachmentAskNext(session);aiRefreshConversation(session,true);return;}const pick=e.target.closest('[data-ai-pick]'),page=e.target.closest('[data-ai-pdf-page]'),matches=e.target.closest('[data-ai-match-review]'),existing=e.target.closest('[data-ai-existing-record]'),separate=e.target.closest('[data-ai-separate-plan]');if(pick){aiPickImage(pick.dataset.aiPick,pick);return;}if(page){aiChangePdfPage(Number(page.dataset.aiPdfPage));return;}if(matches){aiReviewAttachmentMatches(matches);return;}if(existing){const r=allTrackedRecords().find(r=>r.id===existing.dataset.aiExistingRecord);if(r){closeAiImagePreview();openCalendarRecord(r);}return;}if(separate){const session=aiTextSession();session.draft.matchNeedsReview=false;session.draft.matchChoicePlatform=session.draft.platformId||aiNormalizeMerchant(session.draft.name);aiAttachmentAskNext(session);aiRefreshConversation(session,true);return;}if(e.target.closest('[data-ai-image-close]')){closeAiImagePreview();return;}if(!isAiChatScreen())return;const session=aiTextSession(),example=e.target.closest('[data-ai-image-example]'),remove=e.target.closest('[data-ai-image-remove]'),preview=e.target.closest('[data-ai-image-preview]'),open=e.target.closest('[data-ai-image-open]'),discard=e.target.closest('[data-ai-image-discard]'),replace=e.target.closest('[data-ai-image-replace]'),candidate=e.target.closest('[data-ai-image-candidate]');if(example){if(session.thinking||session.saving||session.voiceRecording||session.imageLoading||session.messages.some(m=>m.failed))return;session.imageLoad=(session.imageLoad||0)+1;aiRevokeImage(session.image);session.image=aiImageExample(example.dataset.aiImageExample);session.imageError='';aiRefreshComposer(session);aiRefreshConversation(session);}else if(remove){session.imageLoad=(session.imageLoad||0)+1;aiRevokeImage(session.image);session.image=null;session.imageLoading=false;session.imageError='';aiRefreshComposer(session);aiRefreshConversation(session);document.querySelector('#ai-text-input')?.focus();}else if(preview)openAiImagePreview(preview,session.image);else if(open)openAiImagePreview(open,session.messages.find(m=>m.id===Number(open.dataset.aiImageOpen))?.image);else if(discard)aiRemoveImageMessage(session,Number(discard.dataset.aiImageDiscard));else if(replace){aiRemoveImageMessage(session,Number(replace.dataset.aiImageReplace));aiPickImage();}else if(candidate)aiChooseImageCandidate(session,Number(candidate.dataset.aiImageCandidate));});
document.addEventListener('keydown',e=>{const overlay=document.querySelector('.ai-image-overlay');if(!overlay)return;if(e.key==='Escape'){e.preventDefault();closeAiImagePreview();}else if(e.key==='Tab'){const controls=[...overlay.querySelectorAll('button:not(:disabled),a[href]')],first=controls[0],last=controls.at(-1);if(!overlay.contains(document.activeElement)){e.preventDefault();first.focus();}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});

// Document selection and matching are shared UI contracts; no native picker/backend is implemented here.
let aiPdfPreviewed=null;
function aiAttachmentKind(file){if(['image/png','image/jpeg','image/webp'].includes(file.type))return 'image';if(file.type==='application/pdf'||!file.type&&/\.pdf$/i.test(file.name||''))return 'pdf';return 'unsupported';}
function aiAttachmentFileError(file,choice){const kind=aiAttachmentKind(file);if(kind==='unsupported')return 'Choose PNG, JPG, WebP or PDF. Videos are not supported.';if(choice!==kind)return choice==='pdf'?'Choose a PDF document.':'Choose a PNG, JPG or WebP image.';if(!file.size)return 'This file is empty. Choose another file.';if(file.size>(kind==='pdf'?20:10)*1024*1024)return 'Choose a '+(kind==='pdf'?'PDF of 20 MB':'image of 10 MB')+' or smaller.';return '';}
function aiAttachmentDialog(trigger,title,body,bottom=false){const phone=trigger?.closest('.phone')||document.getElementById('upgraded'),overlay=document.createElement('div');aiAttachmentTrigger=trigger;overlay.className='ai-image-overlay'+(bottom?' ai-attachment-bottom':'');overlay.innerHTML=`<div class="ai-image-shade" data-ai-image-close></div><section class="ai-image-dialog ${bottom?'ai-attachment-sheet':''}" role="dialog" aria-modal="true" aria-labelledby="ai-image-title"><header><h3 id="ai-image-title">${escape(title)}</h3><button data-ai-image-close aria-label="Close attachment view">${aiImageIcon('close')}</button></header>${body}</section>`;for(const el of phone.children)if(!el.inert){el.inert=true;el.dataset.aiImageInert='true';}phone.append(overlay);overlay.querySelector('button').focus();}
function openAiAttachmentPicker(trigger){aiAttachmentDialog(trigger,'Attach a file',`<p class="ai-attach-intro">Share a receipt, invoice or bank statement.</p><div class="ai-attach-options"><button data-ai-pick="image"><span>${aiImageIcon('photo')}</span><div><strong>Image</strong><small>Choose a photo or screenshot</small></div><b aria-hidden="true">›</b></button><button data-ai-pick="pdf"><span class="ai-pdf-symbol">${aiImageIcon('file')}</span><div><strong>PDF document</strong><small>Receipts, invoices and bank statements</small></div><b aria-hidden="true">›</b></button></div>`,true);}
function aiPdfPreviewBody(image){return `<div class="ai-pdf-preview"><p>${escape(image.name)}</p>${image.previewPages?.length?`<img src="${escape(image.previewPages[image.previewPage||0])}" alt="PDF page ${(image.previewPage||0)+1}"><div class="ai-pdf-pagination"><button data-ai-pdf-page="-1" ${(image.previewPage||0)===0?'disabled':''} aria-label="Previous PDF page">‹</button><span role="status" tabindex="-1">Page ${(image.previewPage||0)+1} of ${image.previewPages.length}</span><button data-ai-pdf-page="1" ${(image.previewPage||0)>=image.previewPages.length-1?'disabled':''} aria-label="Next PDF page">›</button></div>`:`<div class="ai-pdf-local-preview">${aiImageIcon('file')}<strong>PDF document</strong><p>Open this file to inspect its contents.</p></div>`}<a href="${escape(image.src)}" target="_blank" rel="noopener noreferrer">Open PDF ↗</a></div>`;}
function aiChangePdfPage(delta){if(!aiPdfPreviewed?.previewPages?.length)return;aiPdfPreviewed.previewPage=Math.max(0,Math.min(aiPdfPreviewed.previewPages.length-1,(aiPdfPreviewed.previewPage||0)+delta));const body=document.querySelector('.ai-pdf-preview');if(body){body.outerHTML=aiPdfPreviewBody(aiPdfPreviewed);const control=document.querySelector('[data-ai-pdf-page="'+delta+'"]');if(control&&!control.disabled)control.focus();else document.querySelector('.ai-pdf-pagination>span')?.focus();}}
function aiNormalizeMerchant(value){return String(value||'').toLowerCase().replace(/[^a-z0-9]/g,'');}
function aiGroundAttachmentDraft(draft,records=[],catalog=[]){const entries=catalog.map(entry=>Array.isArray(entry)?{name:entry[0],category:entry[1],id:entry[2],aliases:entry[3]||[]}:entry),key=aiNormalizeMerchant(draft.name),entry=key?entries.find(p=>[p.name,...(p.aliases||[])].some(value=>aiNormalizeMerchant(value)===key)):undefined;const d={...draft};if(entry){d.name=entry.name;d.platformId=entry.id||null;d.category=entry.category;d.catalogMatch='known';d.platformNeedsReview=false;}else{d.platformId=null;d.catalogMatch='unresolved';d.platformNeedsReview=d.platformNameConfirmed!==aiNormalizeMerchant(d.name);}let possible=records.filter(r=>r.status!=='Deleted'&&!!aiNormalizeMerchant(d.name)&&(entry?.id&&r.platformId?r.platformId===entry.id:aiNormalizeMerchant(r.name)===aiNormalizeMerchant(d.name)));const exact=d.providerSubscriptionId?possible.filter(r=>r.providerSubscriptionId===d.providerSubscriptionId):[];d.matchStrength=exact.length===1?'exact':'possible';if(exact.length===1)possible=exact;d.matchIds=possible.map(r=>r.id);d.matchNeedsReview=possible.length>0&&d.matchChoicePlatform!==(d.platformId||aiNormalizeMerchant(d.name));return d;}
function aiAttachmentMatchNotice(session){const d=session.draft;if(d?.platformNeedsReview)return `<section class="ai-attachment-match"><strong>Confirm the service name</strong><p>No verified platform match. Tell Loop the service name, or keep ${escape(d.name)} as a new service.</p><button data-ai-confirm-service>Use this service name</button></section>`;if(!d?.matchNeedsReview)return '';return `<section class="ai-attachment-match"><strong>Already tracking ${escape(d.name)}?</strong><p>${d.matchIds.length} existing plan${d.matchIds.length===1?'':'s'} found. Review before adding another.</p><div><button data-ai-match-review>View existing</button>${d.matchStrength==='exact'?'':'<button data-ai-separate-plan>This is a separate plan</button>'}</div></section>`;}
function aiReviewAttachmentMatches(trigger){const ids=aiTextSession().draft?.matchIds||[],items=allTrackedRecords().filter(r=>ids.includes(r.id));aiAttachmentDialog(trigger,'Matching subscriptions',`<p class="ai-attach-intro">Choose a plan to view. Nothing will be overwritten.</p><div class="rows subscription-rows">${items.map(r=>subscriptionCard(r,{plan:true,attributes:`data-ai-existing-record="${escape(r.id)}" aria-label="View existing ${escape(r.name)} subscription"`})).join('')}</div>`,true);}
function aiAttachmentRecord(draft,email){const record={};for(const key of ['id','platformId','name','price','currency','cycle','category','renewal','start','note','trialDays','trialEnd','trialEndSource','trialDuration','autoRenew','providerSubscriptionId','inputMode'])if(draft[key]!==undefined)record[key]=draft[key];return {...record,source:'AI',creatorEmail:email,inboxEmail:email,extractionSource:draft.sourceKind==='statement'?'bank-statement':'receipt',...(draft.sourceKind==='statement'?{observedCharge:{date:draft.observedDate,currency:draft.observedCurrency,amount:draft.observedAmount}}:{})};}

function aiAttachmentAskNext(session){const missing=aiTextMissing(session.draft);if(missing)session.messages.push({id:Date.now()+1,role:'assistant',text:aiMissingQuestion(missing,session.draft)});}
